// Some portions generated by Co-Pilot
import { readFileSync } from "fs";
import path from "path";
import { describe, expect, it } from "vitest";
import { processAsciiDoc } from "../asciidoc";

describe("support page", () => {
  it("renders the LTS availability dates and CSPU link", async () => {
    const filePath = path.join(
      process.cwd(),
      "content/asciidoc-pages/support/index.adoc",
    );
    const content = readFileSync(filePath, "utf8");
    const html = await processAsciiDoc(filePath, content);
    const document = new DOMParser().parseFromString(html, "text/html");
    const rows = Array.from(document.querySelectorAll("table tbody tr"));

    for (const [version, date] of [
      ["25", "Sep 2033"],
      ["21", "Sep 2031"],
      ["17", "Jan 2029"],
      ["11", "Jan 2032"],
      ["8", "Dec 2032"],
    ]) {
      const row = rows.find(
        (element) => element.cells[0]?.textContent?.trim() === `Java ${version} (LTS)`,
      );
      expect(row?.cells[4]?.textContent?.trim()).toBe(`At least ${date}`);
    }

    const link = document.querySelector('a[href="https://ops.java/releases/"]');
    expect(link?.textContent).toBe("here");
  });
});
